Stack<int> s;
s.push(1);
s.push(2);
CHECK_EQ(s.size(), 2);
CHECK_EQ(s.pop(), 2);
CHECK_EQ(s.pop(), 1);

Stack<std::string> s;
s.push("a");
s.push("b");
CHECK_EQ(s.top(), std::string("b"));
s.pop();
CHECK_EQ(s.top(), std::string("a"));

Stack<std::string> s;
s.push(std::string("payload"));
std::string out = s.pop();
CHECK_EQ(out, std::string("payload"));
CHECK(s.empty());

Stack<std::unique_ptr<int>> s;
s.push(std::make_unique<int>(9));
std::unique_ptr<int> p = s.pop();
CHECK(p != nullptr);
CHECK_EQ(*p, 9);
CHECK(s.empty());
